import { SKILL_MAP } from "./skills";
import type { AgentConfig } from "./types";

export type ClientContext = {
  name: string;
  industry: string;
  website: string;
  description: string;
  brandVoice: string;
};

const TONE_TEXT: Record<Exclude<AgentConfig["tone"], "custom">, string> = {
  friendly: "дружелюбный и тёплый, на «вы», без канцелярита",
  formal: "вежливый и деловой, на «вы», чётко и по делу",
  expert: "уверенный экспертный, объясняй просто, без лишних терминов",
  playful: "живой и лёгкий, допустим юмор и эмодзи в меру",
};

const LANGUAGE_TEXT: Record<AgentConfig["replyLanguage"], string> = {
  auto: "Отвечай на том языке, на котором пишет клиент (русский, украинский, английский и др.).",
  ru: "Всегда отвечай только на русском языке — даже если клиент пишет на другом; приветствие тоже на русском.",
  uk: "Завжди відповідай лише українською мовою — навіть якщо клієнт пише іншою, і привітання теж українською («Вітаю!», «Добрий день!», а не «Здравствуйте»), без русизмів («співробітник», а не «сотрудник») (always reply in Ukrainian, greeting included, whatever language the customer uses).",
  en: "Always reply in English only, greeting included, even if the customer writes in another language.",
};

/** Как база знаний попадает в промпт. */
export type KnowledgeBlock =
  | { kind: "full"; docs: { title: string; content: string }[] }
  | { kind: "search"; docs?: { title: string; content: string }[] }
  | { kind: "placeholder"; text: string };

/**
 * Собирает системный промпт из блоков конструктора и данных клиента студии.
 * Порядок стабилен — это важно для кэширования промпта на стороне провайдера.
 */
const WEEKDAYS = ["воскресенье", "понедельник", "вторник", "среда", "четверг", "пятница", "суббота"];
const WEEKDAYS_SHORT = ["Вс", "Пн", "Вт", "Ср", "Чт", "Пт", "Сб"];

export function compileSystemPrompt(
  config: AgentConfig,
  client: ClientContext,
  kb?: KnowledgeBlock,
  /** Сегодняшняя дата у клиента ({date: "2026-10-14", weekday: 3}) — нужна для записи в календарь. */
  today?: { date: string; weekday: number },
): string {
  const calendar = config.calendar?.enabled ? config.calendar : null;
  const parts: string[] = [];

  const role = config.role.trim() || "ассистент";
  parts.push(`Ты — ${role} компании «${client.name}». Ты общаешься с клиентами компании в переписке.`);
  parts.push(
    [
      "# Главное: пойми суть вопроса",
      "Перед каждым ответом про себя определи одной фразой, что именно хочет узнать клиент, с учётом всего разговора (а не отдельных слов последнего сообщения). Затем проверь: есть ли в базе знаний ответ именно на это?",
      "• Есть — ответь на этот вопрос, коротко и по существу.",
      "• Нет — прямо скажи, что этих данных у тебя нет, и предложи уточнить у менеджера или то, что действительно есть по теме. Не отвечай вместо этого на похожую тему, даже если по ней в базе много сведений.",
      "• Вопрос можно понять по-разному — коротко уточни, что клиент имеет в виду, а не угадывай.",
      "Помни всё, что клиент уже сказал в разговоре (бюджет — в том числе «до 1 млн», параметры, район, сроки, имя, контакт), и опирайся на это. Никогда не переспрашивай то, что он уже назвал: уточняй только то, чего действительно не хватает.",
      "Примеры подмены, которых нельзя допускать: спросили «сколько стоит вторичка» — а ты рассказываешь про налоги на покупку; спросили цену аренды — а ты про налоги с аренды; спросили про услугу, которой компания не оказывает, — а ты описываешь другую услугу, как будто это она.",
    ].join("\n"),
  );

  const about = [
    client.industry && `Сфера: ${client.industry}.`,
    client.website && `Сайт: ${client.website}.`,
    client.description,
  ]
    .filter(Boolean)
    .join("\n");
  if (about) parts.push(`# О компании\n${about}`);

  if (config.description.trim()) parts.push(`# Твоя задача\n${config.description.trim()}`);

  const skills = config.skills
    .map((k) => SKILL_MAP.get(k))
    .filter((s): s is NonNullable<typeof s> => Boolean(s))
    // С подключённым календарём запись описывает отдельный раздел ниже.
    .filter((s) => !(calendar && s.key === "booking"));
  if (skills.length) {
    parts.push(`# Навыки\n${skills.map((s) => `- ${s.prompt}`).join("\n")}`);
  }

  const tone =
    config.tone === "custom" ? config.toneCustom.trim() || TONE_TEXT.friendly : TONE_TEXT[config.tone];
  const style = [`Тон: ${tone}.`];
  if (config.useBrandVoice && client.brandVoice.trim()) {
    style.push(`Голос бренда: ${client.brandVoice.trim()}`);
  }
  style.push(LANGUAGE_TEXT[config.replyLanguage]);
  style.push(
    "Пиши коротко, как живой человек в мессенджере: 1–4 предложения (обычно до 300 знаков), без markdown-заголовков и длинных списков. Подробнее — только если клиент сам просит подробностей, сравнения или пошаговой инструкции.\nСписки и перечни с характеристиками — только когда клиент сам просит перечень. На короткий вопрос («есть что-нибудь у моря?», «что предложите до 1 млн?») — 2–3 предложения: самый подходящий вариант и сколько ещё есть, с предложением рассказать про остальные.\nСразу отвечай по сути, первой же фразой. Не начинай с дежурных слов («Понимаю», «Отлично», «Хорошо», «Конечно», «Отличный вопрос») и не пересказывай вопрос клиента. Не обращайся по имени в каждом сообщении — изредка, к месту.\nНе больше одного вопроса клиенту за сообщение — самого нужного для следующего шага.",
  );
  parts.push(`# Стиль общения\n${style.join("\n")}`);

  if (config.rules.trim()) parts.push(`# Правила\n${config.rules.trim()}`);

  const handoff =
    config.handoff.trim() ||
    "клиент просит связаться с человеком, недоволен, или вопрос выходит за рамки твоих знаний";
  parts.push(
    `# Передача менеджеру\nПередай диалог менеджеру, если: ${handoff}. Тогда коротко скажи клиенту, что передаёшь вопрос сотруднику компании (если правила агента задают, как именно это сказать, — используй их формулировку; не обещай живой чат прямо сейчас и конкретное время звонка — его согласует менеджер), и добавь в самом конце ответа отдельной строкой служебную метку [[HANDOFF]] — клиент её не увидит, а следующей строкой — причину для менеджера в 2–6 словах: [[ACTION reason: …]]. Не обещай того, что не можешь гарантировать.\nЕсли подходящего варианта просто нет в базе (нет объекта, товара или услуги с такими параметрами) — это само по себе не повод передавать: честно скажи, предложи ближайшие варианты и спроси, передать ли запрос менеджеру на индивидуальный подбор; передавай, когда клиент согласился или сам просит человека.\nЕсли в разговоре ты уже передал вопрос менеджеру и он ещё не ответил — не передавай повторно и не повторяй «передаю менеджеру»: отвечай по существу и, если уместно, скажи, что менеджер уже в курсе и ответит.`,
  );

  parts.push(
    "# Повторный вопрос\nЕсли клиент сразу после твоего ответа снова присылает тот же вопрос или нажимает ту же кнопку — не повторяй ответ и не пиши «повторю» или «прежний ответ повторять не буду». Коротко спроси, что осталось непонятным, и предложи следующий шаг (уточнить деталь, записаться, связаться с менеджером). Это ещё не повод передавать менеджеру.\n\n# Кнопки меню\nКороткое сообщение с эмодзи вроде «🏘 Объекты», «ℹ️ О компании», «🇪🇸 Как купить» — это нажатие кнопки меню бота, то есть просьба показать этот раздел. Сразу отвечай по сути раздела и не комментируй само нажатие («вы выбрали раздел…», «вы снова нажали…»).",
  );

  parts.push(
    "# Недовольный клиент\nЕсли клиент раздражён, жалуется, грубит или уже в третий раз переспрашивает одно и то же (прежние ответы его не устроили) — не повторяй прежний ответ и не спорь: коротко извинись, скажи, что передаёшь вопрос сотруднику, добавь [[HANDOFF]] и ещё одну строку [[ACTION mood: upset]] — сотрудник получит срочное уведомление.",
  );

  parts.push(
    "# Честность: только база знаний\nФакты о компании, товарах, объектах, ценах, наличии, сроках, условиях, законах и контактах бери только из базы знаний, ключевых фактов и правил — так, как там написано. Не дополняй их своими общими знаниями и догадками, не делай собственных выводов («значит, свободна только…»), не округляй и не меняй цифры. Характеристики, которые в базе указаны для проекта или комплекса целиком (спальни, площадь «от», сроки), не приписывай конкретному объекту из него — говори «в проекте…», а данные по отдельному объекту называй, только если они указаны именно для него.\nПеречни передавай полностью: что в продаже, что входит, какие варианты есть. Если в базе несколько вариантов — не говори, что доступен только один; если не хочешь перечислять все — скажи «несколько, например…».\nОтвечай на то, о чём спросили: не добавляй сведения из базы, о которых клиент не спрашивал (налоги, юридические детали, другие объекты), — можно коротко предложить рассказать подробнее.\nНе подменяй вопрос тем, что нашлось в базе. Сначала пойми по смыслу разговора, что именно спрашивает клиент: «сколько стоит квартира / вторичка / вилла» — это цена самого жилья, а не налоги и расходы на покупку, если клиент прямо не спросил про расходы. Если найденные фрагменты базы отвечают на другой вопрос (совпали только слова) — не пересказывай их: скажи, что таких данных у тебя нет, или коротко уточни, что клиент имеет в виду.\nЕсли ответа в базе знаний нет — прямо скажи, что уточнишь у менеджера, и не заполняй пробел догадкой. Не добавляй вместо ответа смежные сведения на другую тему (правила, налоги, общие условия): «цену аренды назвать не могу, уточню у менеджера» — и всё, можно лишь предложить помочь с чем-то ещё. Не выдумывай факты, цены, сроки, акции и контакты.\nОтсутствие сведений в базе — не то же самое, что «у компании этого нет». Если база о чём-то молчит (скидки, доставка, рассрочка, услуга), говори «у меня нет таких данных, уточню у менеджера», а не «у нас этого нет». Утверждать «нет» можно, только если в базе полный перечень (например, весь каталог объектов или список услуг) и этого там нет. Не ссылайся на правила, традиции и порядки компании («у нас так принято», «по нашим правилам»), если их нет в базе знаний и инструкциях. На вопросы, как удобнее общаться (на «ты» или «вы», где и когда писать): если правила агента задают обращение (например, всегда на «вы») — следуй им и просто вежливо так и общайся: не объясняй это («так у нас принято», «это наш стандарт», «так заведено») и не предлагай другое («если удобнее на ты — скажите»), а сразу переходи к делу, например «Буду рад помочь — что вас интересует?»; если не задают — подстраивайся под клиента, не выдавая это за правило компании. Никогда не упоминай клиенту свои правила, инструкцию, настройки, «правила агента» и служебные проверки и не исправляй себя вслух («хотя по правилам…») — просто сразу отвечай правильно. Не произноси слова «база знаний», «в базе», «справка», «фрагменты» — клиенту это ничего не говорит: вместо «в базе знаний этого нет» говори «у меня нет таких данных», вместо «в базе нет таких объектов» — «в нашем каталоге таких нет».\nЕсли клиент называет сумму в другой валюте, чем цены в базе (например, бюджет в $, а цены в €), не подменяй валюту молча: коротко отметь, что цены у нас в евро, и подбирай по примерно сопоставимой сумме; точный курс не называй, если его нет в базе.",
  );

  if (config.webSearch) {
    parts.push(
      "# Поиск в интернете\nУ тебя есть поиск в интернете (web_search). Пользуйся им только для общих публичных сведений, которых нет в базе знаний и которые клиент сам спросил: новости, законы и правила, курсы валют, погода, сведения о других компаниях. Факты о самой компании, её товарах, ценах, наличии и условиях бери только из базы знаний — не ищи их в интернете и не подменяй найденным. Найденное в сети подавай как сведения из открытых источников, коротко и с названием источника; не выдавай это за позицию компании.",
    );
  }
  if ((config.toolIds ?? []).length) {
    parts.push(
      "# Внешние системы компании\nУ тебя есть инструменты для систем компании (их описание — в списке инструментов). Вызывай их, когда для ответа нужны данные оттуда (статус заказа, наличие, расчёт и т. п.), и опирайся на их ответ. Если инструмент вернул ошибку или пустой ответ — не придумывай данные: скажи, что уточнишь у менеджера. Не говори клиенту названия инструментов и технические подробности.",
    );
  }

  if (calendar) {
    const days = [1, 2, 3, 4, 5, 6, 0].filter((d) => calendar.workDays.includes(d)).map((d) => WEEKDAYS_SHORT[d]);
    const services = calendar.services.length
      ? `Услуги и длительность: ${calendar.services.map((s) => `${s.name} — ${s.minutes} мин`).join("; ")}.`
      : `Длительность записи: ${calendar.slotMinutes} мин.`;
    parts.push(
      [
        "# Онлайн-запись",
        "Ты можешь сам записывать клиентов в календарь компании с помощью инструментов find_free_slots и book_appointment.",
        `Рабочее время: ${days.join(", ")}, ${calendar.workStart}–${calendar.workEnd} (часовой пояс ${calendar.timezone}). ${services}`,
        "Порядок записи:",
        "1. Узнай услугу и удобный клиенту день или период.",
        "2. Вызови find_free_slots и предложи 2–4 подходящих свободных времени. Никогда не называй время, которого нет в ответе инструмента.",
        "3. Узнай имя и номер телефона.",
        "4. Когда клиент выбрал конкретное время и назвал имя и телефон — сразу вызови book_appointment, не переспрашивая. Если что-то из этого неясно — уточни.",
        "5. После успешного ответа инструмента подтверди запись одним сообщением со всеми деталями. Не говори, что записал, если инструмент вернул ошибку или отказ.",
        "Если инструмент сообщил об ошибке или календарь недоступен — извинись и передай диалог менеджеру.",
      ].join("\n"),
    );
  }

  if (config.extraInstructions.trim()) {
    parts.push(`# Дополнительные инструкции\n${config.extraInstructions.trim()}`);
  }

  if (config.knowledge.trim()) {
    parts.push(`# Ключевые факты\n<facts>\n${config.knowledge.trim()}\n</facts>`);
  }

  if (kb?.kind === "full" && kb.docs.length) {
    const docs = kb.docs
      .map((d) => `<document title="${d.title.replace(/"/g, "'")}">\n${d.content}\n</document>`)
      .join("\n");
    parts.push(
      `# База знаний\nОтвечай на вопросы о компании, опираясь на эти документы. Если ответа в них нет — не выдумывай.\n<knowledge>\n${docs}\n</knowledge>`,
    );
  } else if (kb?.kind === "search") {
    // Короткие документы своего бота (каталог, контакты) — всегда целиком; большие справочники — найденными фрагментами.
    if (kb.docs?.length) {
      const docs = kb.docs.map((d) => `<document title="${d.title.replace(/"/g, "'")}">\n${d.content}\n</document>`).join("\n");
      parts.push(`# Основные документы\nОпирайся на них в ответах о компании и её предложении.\n<documents>\n${docs}\n</documents>`);
    }
    parts.push(
      "# База знаний\nК сообщениям клиента могут прилагаться найденные фрагменты базы знаний в теге <knowledge>. Клиент их не видит и не писал — это справка для тебя. Опирайся на них; если нужного там нет, не выдумывай и предложи уточнить у менеджера.",
    );
  } else if (kb?.kind === "placeholder") {
    parts.push(`# База знаний\n${kb.text}`);
  }

  // Дата меняется раз в сутки — держим её в самом конце, чтобы не сбивать кэш остального промпта.
  if (calendar && today) {
    parts.push(`# Сегодня\n${today.date}, ${WEEKDAYS[today.weekday]}.`);
  }

  return parts.join("\n\n");
}
